promptBlocks.text:
{
  "task": "Photorealistic 6-panel automotive editorial grid. One white Porsche 911 GT3 RS photographed from multiple angles in front of a colossal white building whose architecture is derived from the same car's design language. Two panels show the interior. All six panels are real photographs from one shoot, same car, same location, same light.",
  "references": {
    "image_1": "Car identity and form reference. Read the exact body shape, wing, wheels, stance, ride height, white paint finish and all proportions from this image. Do not reinterpret the car. Do not add or remove aero parts. The warm beige-peach tonality of this image is the color world of the whole grid."
  },
  "layout": {
    "format": "single 16:9 image divided into a clean 2x3 grid, three panels per row",
    "gutters": "thin uniform off-white gutters between panels, equal width, no rounded corners, no drop shadows, no labels, no numbers",
    "consistency": "identical car, identical building, identical time of day and light direction in every panel"
  },
  "environment": {
    "building": "A colossal white monolithic building designed as a piece of Porsche GT3 RS architecture. The facade is smooth white gloss-ceramic panels that mirror the car's paint. The wide rear wheel arches of the car become two enormous curved white volumes at the building's base. The GT3 RS swan-neck rear wing becomes a cantilevered white roof canopy, nine storeys up, supported by two slim angled struts. The car's side air intakes become tall louvered black window slots cut into the facade. A single continuous horizontal red LED light bar runs across the building like the car's rear taillight strip. The word 'PORSCHE' appears once, in the brand's real letterspaced capitals, as a very large brushed-metal sign on the upper facade, and the crest appears once, small, at the entrance. The building is scaled so the car looks small in front of it.",
    "ground": "A vast empty plaza of smooth pale sand-colored concrete, wide seamless slabs, faint tire dust marks, a few subtle expansion joints. No other cars, no people.",
    "sky": "Warm hazy late-afternoon sky in soft beige and peach, no clouds, matching the tonality of [Image 1]."
  },
  "vehicle": {
    "identity": "[Image 1] car, unchanged. White paint with real gloss depth and slight orange-peel reflection, not a flat render white.",
    "interior": "Premium fully leather-trimmed cabin in two tones: cognac brown and warm cream. Cream leather sport bucket seats with cognac bolsters, fine cognac contrast stitching, perforated center panels, a small embossed Porsche crest on the headrests. Cognac leather dashboard top with cream lower dashboard, cream leather door panels with cognac armrests, cognac Alcantara-free full leather steering wheel with a yellow 12 o'clock marker, carbon fiber trim on the center console, matte black metal paddle shifters, digital instrument cluster switched on with the tachometer glowing. Cream Alcantara headliner. Every surface shows real leather grain, slight natural creasing on the seat cushions, and honest reflections."
  },
  "panels": [
    {
      "panel": 1,
      "position": "top-left",
      "shot": "Wide establishing shot, front three-quarter view of the car, camera at knee height 24mm, the car parked dead center of the plaza with the entire building rising behind it. Car occupies the lower third of the frame, building fills the rest."
    },
    {
      "panel": 2,
      "position": "top-center",
      "shot": "Rear three-quarter view matching the angle of [Image 1], camera at hip height 35mm, the rear wing of the car visually aligned under the building's wing-shaped roof canopy so the two shapes echo each other."
    },
    {
      "panel": 3,
      "position": "top-right",
      "shot": "Pure side profile, camera exactly perpendicular to the car at wheel-hub height, 85mm from far back for compressed perspective, the horizontal red light bar of the building running straight across the background behind the car."
    },
    {
      "panel": 4,
      "position": "bottom-left",
      "shot": "Direct low front view, camera 30cm above the ground, 24mm, the car's nose filling the lower frame, the building's two arch-shaped base volumes framing the car on both sides."
    },
    {
      "panel": 5,
      "position": "bottom-center",
      "shot": "Interior, driver's cockpit shot from the open driver door at seat height, 24mm, showing the cream and cognac bucket seat, the steering wheel with yellow marker, the glowing cluster, the carbon center console. Warm light from outside falls across the leather. The white building is softly visible through the windshield."
    },
    {
      "panel": 6,
      "position": "bottom-right",
      "shot": "Interior detail, close 50mm shot from the passenger side looking across both seats, focus on the cognac contrast stitching and perforated cream leather of the seat bolster, the door panel and cognac armrest in the foreground, shallow depth of field, the driver's seat softly blurred behind."
    }
  ],
  "camera_and_light": {
    "camera": "Phase One IQ4 medium format for exterior panels, Canon 5D Mark IV for interior panels, all handheld on a real shoot, exteriors at f/8 with deep focus, interiors at f/2.8.",
    "light": "Low warm sun from camera-left at roughly 20 degrees above the horizon, long soft shadows stretching to the right across the plaza, warm highlights and slightly cooler shadows, gentle atmospheric haze softening the top of the building.",
    "grade": "Muted warm grade in beige, peach and cream, whites kept slightly warm not clinical, blacks lifted a touch, fine medium-format sensor grain visible in the sky and shadows, subtle halation on the red light bar and on chrome edges."
  },
  "quality_constraints": {
    "realism": "These are real photographs, not renders. Real paint reflections with slight distortion, tire sidewall texture with visible lettering, brake dust on the wheel barrels, faint dust on the plaza, real leather grain and creasing. No CGI smoothness, no perfectly even studio lighting, no floating car, tires sit with real contact shadow.",
    "banned": "no text other than 'PORSCHE' and the crest, no watermark, no panel numbers, no captions, no extra cars, no people, no reflections revealing a studio, no duplicated or mirrored panels, no fantasy elements, no glowing edges, no digital art look",
    "identity_lock": "the car in all four exterior panels must be pixel-consistent with [Image 1] in shape, wing, wheels and stance"
  }
}
